import{_ as r,a0 as p,w as o,s as d,ao as l,I as e,x as i,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Arch Linux 中安裝 MATE 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中安裝 MATE 桌面 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中安裝 MATE 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中安裝 MATE 桌面 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide]","title":"如何在 Arch Linux 中安裝 MATE 桌面","tag":"202302","desc":""},"relativePath":"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide].md","filePath":"[post].md"}'),h={name:"202302/20221106.1 ⭐️ How to Install MATE Desktop in Arch Linux [Complete Guide].md"};function u(g,t,m,A,k,T){const s=p("Link");return o(),d("div",null,[t[24]||(t[24]=l('<h1 id="如何在-arch-linux-中安裝-mate-桌面" tabindex="-1">如何在 Arch Linux 中安裝 MATE 桌面 <a class="header-anchor" href="#如何在-arch-linux-中安裝-mate-桌面" aria-label="Permalink to “如何在 Arch Linux 中安裝 MATE 桌面”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/21/104424o8p78qj8gp5hqghj.jpg" alt=""></p><blockquote><p>本指南將詳細解釋你在 Arch Linux 中安裝 MATE 桌面所需的步驟。</p></blockquote><p>本指南分為兩部分。第一部分討論安裝基礎 Arch 系統。第二部分是在 Arch Linux 上安裝完整的 MATE 桌面環境。</p><p>本文在以下版本中進行了測試：MATE 1.24 和 MATE 1.26。</p><h3 id="什麼是-mate-桌面" tabindex="-1">什麼是 MATE 桌面? <a class="header-anchor" href="#什麼是-mate-桌面" aria-label="Permalink to “什麼是 MATE 桌面?”">​</a></h3><p>當 GNOME 桌面從 GNOME 2 改變方向到 GNOME 3 時，改變了用户交互和界面，MATE 桌面仍然延續了“較舊的”或者説“傳統的” GNOME 2 的開發方向。因此，MATE 桌面環境保留了 Linux 中的傳統桌面體驗。它速度快，內存消耗低。在我看來，MATE 桌面環境是一個被低估的桌面環境，需要更多的關注！</p>',7)),e("p",null,[t[1]||(t[1]=i("MATE 團隊一直在繼續開發，它是一個基於 GNOME 2 的流行桌面之一，但同時支持更新的技術。你可以在其 ",-1)),a(s,{href:"https://mate-desktop.org/"},{default:n(()=>[...t[0]||(t[0]=[i("官方網站",-1)])]),_:1}),t[2]||(t[2]=i(" 上了解更多信息。",-1))]),t[25]||(t[25]=e("h3",{id:"在-arch-linux-中安裝-mate-桌面",tabindex:"-1"},[i("在 Arch Linux 中安裝 MATE 桌面 "),e("a",{class:"header-anchor",href:"#在-arch-linux-中安裝-mate-桌面","aria-label":"Permalink to “在 Arch Linux 中安裝 MATE 桌面”"},"​")],-1)),t[26]||(t[26]=e("h4",{id:"第一部分-安裝-arch-linux",tabindex:"-1"},[i("第一部分: 安裝 Arch Linux "),e("a",{class:"header-anchor",href:"#第一部分-安裝-arch-linux","aria-label":"Permalink to “第一部分: 安裝 Arch Linux”"},"​")],-1)),t[27]||(t[27]=e("p",null,"如果你已經安裝了 Arch Linux，則可以跳過此步驟，直接轉到下面的 MATE 桌面安裝部分。",-1)),e("p",null,[t[4]||(t[4]=i("要快速安裝 Arch Linux，請按照這個自動化的 ",-1)),a(s,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:n(()=>[...t[3]||(t[3]=[i("archinstall 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 進行操作，該指南非常容易上手。安裝完成後，繼續至第二部分。",-1))]),t[28]||(t[28]=l('<h4 id="第二部分-在-arch-linux-中安裝-mate-桌面" tabindex="-1">第二部分：在 Arch Linux 中安裝 MATE 桌面 <a class="header-anchor" href="#第二部分-在-arch-linux-中安裝-mate-桌面" aria-label="Permalink to “第二部分：在 Arch Linux 中安裝 MATE 桌面”">​</a></h4><p>重新啓動後，從 GRUB 中選擇 Arch Linux。在 Arch Linux 提示符下，按順序運行以下命令。這些命令將安裝 Xorg 服務器、顯示管理器、MATE 桌面組件、控制器包以及其他應用程序。</p><p>對於所有命令，請使用默認值，即在詢問時按 Enter 鍵。</p><p>安裝 Xorg。安裝大小大約為 80 MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed xorg</span></span></code></pre></div><p>安裝顯示管理器和 MATE 桌面組件。安裝大小大約為 380 MB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed mate mate-extra ttf-freefont lightdm lightdm-gtk-greeter</span></span></code></pre></div>',7)),e("blockquote",null,[e("p",null,[t[7]||(t[7]=i("LCTT 譯註：在 Arch Linux 中，很多時候 lightdm 顯示管理器需要額外的配置才能正常啓用。可以參考：",-1)),a(s,{href:"https://wiki.archlinux.org/title/LightDM"},{default:n(()=>[...t[6]||(t[6]=[i("LightDM - ArchWiki",-1)])]),_:1}),t[8]||(t[8]=i("。除此之外，可以安裝 lightdm-gtk-greeter-settings 來對 lightdm-gtk-greeter 進行配置。",-1))])]),t[29]||(t[29]=l(`<p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/Installing-MATE-Packages.jpg" alt="安裝 MATE 包"></p><p>安裝應用軟件：</p><p>這只是一個參考。你也可以安裝你所需要的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed firefox vlc filezilla leafpad xscreensaver archlinux-wallpaper</span></span></code></pre></div><p>現在是時候以服務的方式啓用顯示管理器和網絡管理器了。這樣，下次登錄時，它們就可以通過 systemd 自動運行了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable lightdm</span></span>
<span class="line"><span>systemctl enable NetworkManager</span></span></code></pre></div><p>使用重啓命令重啓系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>如果一切順利，你應該在 MATE 桌面上看到登錄提示。</p><p>現在你可以使用剛剛創建的用户 ID 和密碼登錄。一個超快速和傳統的 MATE 桌面將歡迎你的到來。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/MATE-Desktop-in-Arch-Linux-1.jpg" alt="Arch Linux 中的 MATE 桌面"></p><p>我希望本指南能幫助你從頭開始創建自己的 Arch Linux 環境，並使用傳統的 MATE 桌面。</p><hr>`,13)),e("p",null,[t[10]||(t[10]=i("via: ",-1)),a(s,{href:"https://www.debugpoint.com/mate-desktop-arch-linux-install/"},{default:n(()=>[...t[9]||(t[9]=[i("https://www.debugpoint.com/mate-desktop-arch-linux-install/",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=i("作者：",-1)),a(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[11]||(t[11]=[i("Arindam",-1)])]),_:1}),t[16]||(t[16]=i(" 選題：",-1)),a(s,{href:"https://github.com/lkxed"},{default:n(()=>[...t[12]||(t[12]=[i("lkxed",-1)])]),_:1}),t[17]||(t[17]=i(" 譯者：",-1)),a(s,{href:"https://github.com/Chao-zhi"},{default:n(()=>[...t[13]||(t[13]=[i("Chao-zhi",-1)])]),_:1}),t[18]||(t[18]=i(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[i("Linux中國",-1)])]),_:1}),t[23]||(t[23]=i(" 榮譽推出",-1))])])}const M=r(h,[["render",u]]);export{f as __pageData,M as default};
